    Dialog full(String title,View content){Dialog dialog=new Dialog(a){final GestureRules edges=new GestureRules(a.getResources().getDisplayMetrics().density);boolean tracking,consumed;final Runnable hold=new Runnable(){public void run(){if(!tracking)return;GestureRules.Action result=edges.poll(SystemClock.uptimeMillis());if(result==GestureRules.Action.RECENTS){tracking=false;consumed=true;dismiss();a.showRecents();}else a.handler.postDelayed(this,80);}};@Override public boolean dispatchTouchEvent(MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){int w=getWindow().getDecorView().getWidth(),h=getWindow().getDecorView().getHeight();float edge=a.dp(20);tracking=event.getX()<edge||event.getX()>w-edge||event.getY()>h-a.dp(28);consumed=false;if(tracking){edges.down(event.getX(),event.getY(),w,h,SystemClock.uptimeMillis());a.handler.postDelayed(hold,80);}}GestureRules.Action result=GestureRules.Action.NONE;if(tracking&&action==MotionEvent.ACTION_MOVE)result=edges.move(event.getX(),event.getY(),SystemClock.uptimeMillis());if(action==MotionEvent.ACTION_UP){if(tracking)result=edges.up(event.getX(),event.getY(),SystemClock.uptimeMillis());tracking=false;a.handler.removeCallbacks(hold);}if(action==MotionEvent.ACTION_CANCEL){tracking=false;edges.cancel();a.handler.removeCallbacks(hold);}if(result==GestureRules.Action.BACK||result==GestureRules.Action.HOME||result==GestureRules.Action.RECENTS){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();consumed=true;dismiss();if(result!=GestureRules.Action.BACK)a.homeAction(result);return true;}if(consumed)return true;return super.dispatchTouchEvent(event);}@Override public void dismiss(){tracking=false;a.handler.removeCallbacks(hold);super.dismiss();}};GlassPanel glass=new GlassPanel(a,a,"home",0);LinearLayout body=a.column(a);body.setPadding(a.dp(18),a.insetTop+a.dp(12),a.dp(18),a.insetBottom+a.dp(12));LinearLayout header=a.row(a);TextView name=a.text(a,title,24);name.setTypeface(null,Typeface.BOLD);header.addView(name,new LinearLayout.LayoutParams(0,a.dp(64),1));header.addView(a.action(a,"✕",dialog::dismiss));body.addView(header);body.addView(content,new LinearLayout.LayoutParams(-1,0,1));glass.addView(body,new android.widget.FrameLayout.LayoutParams(-1,-1));dialog.setContentView(glass);dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.getWindow().setDimAmount(0);a.dialogs.add(dialog);dialog.setOnDismissListener(d->{a.dialogs.remove(dialog);a.gestureCaptured=false;a.gestureDown=false;a.handler.removeCallbacks(a.holdGesture);a.gestures.cancel();});dialog.show();dialog.getWindow().setLayout(-1,-1);return dialog;}
    void notifications(){ScrollView scroll=new ScrollView(a);notificationList=a.column(a);scroll.addView(notificationList);notificationDialog=full("Notifications",scroll);refreshNotifications();}
    void refreshNotifications(){if(notificationDialog==null||!notificationDialog.isShowing())return;notificationList.removeAllViews();
        if(AuraNotifications.active==null){TextView why=a.text(a,"Show your notifications here with Android’s notification-access permission. Notification content stays on this device.",17);why.setPadding(a.dp(8),a.dp(24),a.dp(8),a.dp(20));notificationList.addView(why);notificationList.addView(a.action(a,"Enable notification access",()->a.open(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))));return;}
        StatusBarNotification[] notifications=AuraNotifications.notifications();Arrays.sort(notifications,(x,y)->Long.compare(y.getPostTime(),x.getPostTime()));
        notificationList.addView(a.action(a,"Clear dismissible notifications",()->{try{AuraNotifications.active.cancelAllNotifications();}catch(Exception ignored){}refreshNotifications();}));
        if(notifications.length==0){TextView empty=a.text(a,"No notifications",20);empty.setGravity(Gravity.CENTER);notificationList.addView(empty,new LinearLayout.LayoutParams(-1,a.dp(180)));}
        for(StatusBarNotification item:notifications){Notification n=item.getNotification();GlassPanel card=new GlassPanel(a,a,"home");LinearLayout rows=a.column(a);rows.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(14));LinearLayout top=a.row(a);String label=item.getPackageName();try{label=a.getPackageManager().getApplicationLabel(a.getPackageManager().getApplicationInfo(label,0)).toString();}catch(Exception ignored){}
            TextView app=a.text(a,label+"  ·  "+new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(item.getPostTime())),12);top.addView(app,new LinearLayout.LayoutParams(0,-2,1));if(item.isClearable())top.addView(a.action(a,"✕",()->{try{AuraNotifications.active.cancelNotification(item.getKey());}catch(Exception ignored){}refreshNotifications();}));rows.addView(top);
            CharSequence title=n.extras.getCharSequence(Notification.EXTRA_TITLE,""),message=n.extras.getCharSequence(Notification.EXTRA_BIG_TEXT);if(message==null)message=n.extras.getCharSequence(Notification.EXTRA_TEXT,"");TextView headline=a.text(a,title.toString(),17);headline.setTypeface(null,Typeface.BOLD);rows.addView(headline);TextView text=a.text(a,message.toString(),14);text.setPadding(0,a.dp(5),0,a.dp(8));rows.addView(text);
            if(n.actions!=null){LinearLayout actions=a.row(a);for(Notification.Action action:n.actions)if(action.actionIntent!=null)actions.addView(a.action(a,action.title.toString(),()->send(action.actionIntent,null)));rows.addView(actions);}
            card.addView(rows);card.setOnClickListener(v->send(n.contentIntent,item));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,a.dp(6),0,a.dp(6));notificationList.addView(card,cp);
        }
    }
    void send(PendingIntent intent,StatusBarNotification item){if(intent==null)return;try{ActivityOptions options=ActivityOptions.makeBasic();if(Build.VERSION.SDK_INT>=34)options.setPendingIntentBackgroundActivityStartMode(ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);intent.send(a,0,null,null,null,null,options.toBundle());if(item!=null&&(item.getNotification().flags&Notification.FLAG_AUTO_CANCEL)!=0&&AuraNotifications.active!=null)AuraNotifications.active.cancelNotification(item.getKey());if(notificationDialog!=null)notificationDialog.dismiss();}catch(Exception e){a.toast("This notification action is no longer available.");}}
    void control(){LinearLayout box=a.column(a);TextView date=a.text(a,new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),15);date.setPadding(a.dp(8),0,0,a.dp(20));box.addView(date);GridLayout tiles=new GridLayout(a);tiles.setColumnCount(2);
        boolean wifi=false;try{ConnectivityManager cm=a.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm.getNetworkCapabilities(cm.getActiveNetwork());wifi=caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);}catch(Exception ignored){}
        tile(tiles,"Wi-Fi",wifi?"Connected":"Network settings",wifi,()->a.open(new Intent(Build.VERSION.SDK_INT>=29?Settings.Panel.ACTION_WIFI:Settings.ACTION_WIFI_SETTINGS)));
        tile(tiles,"Bluetooth","Device settings",false,()->a.open(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS)));
        tile(tiles,"Mobile data","Internet settings",false,()->a.open(new Intent(Build.VERSION.SDK_INT>=29?Settings.Panel.ACTION_INTERNET_CONNECTIVITY:Settings.ACTION_WIRELESS_SETTINGS)));
        tile(tiles,"Airplane mode",Settings.Global.getInt(a.getContentResolver(),Settings.Global.AIRPLANE_MODE_ON,0)==1?"On":"Off",Settings.Global.getInt(a.getContentResolver(),Settings.Global.AIRPLANE_MODE_ON,0)==1,()->a.open(new Intent(Settings.ACTION_AIRPLANE_MODE_SETTINGS)));
        box.addView(tiles,new LinearLayout.LayoutParams(-1,-2));
        AudioManager audio=a.getSystemService(AudioManager.class);int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC),volume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);slider(box,"Volume",volume,max,value->audio.setStreamVolume(AudioManager.STREAM_MUSIC,value,0));
        int brightness=Settings.System.getInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,140);boolean systemBrightness=Settings.System.canWrite(a);slider(box,systemBrightness?"Brightness":"Brightness · Aura only",brightness,255,value->{if(Settings.System.canWrite(a)){Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL);Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,Math.max(1,value));}else{WindowManager.LayoutParams attrs=a.getWindow().getAttributes();attrs.screenBrightness=Math.max(.02f,value/255f);a.getWindow().setAttributes(attrs);}});
        if(!systemBrightness)box.addView(a.action(a,"Allow system brightness control",()->a.open(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:"+a.getPackageName())))));
        LinearLayout quick=a.row(a);quick.addView(a.action(a,"Torch",this::torch));quick.addView(a.action(a,"Sound",()->{try{audio.setRingerMode(audio.getRingerMode()==AudioManager.RINGER_MODE_NORMAL?AudioManager.RINGER_MODE_VIBRATE:AudioManager.RINGER_MODE_NORMAL);}catch(Exception e){a.open(new Intent(Settings.ACTION_SOUND_SETTINGS));}}));quick.addView(a.action(a,"Rotate",()->{if(Settings.System.canWrite(a)){int enabled=Settings.System.getInt(a.getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,1);Settings.System.putInt(a.getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,1-enabled);a.toast(enabled==1?"Rotation locked":"Auto-rotate enabled");}else a.open(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:"+a.getPackageName())));}));box.addView(quick);
        media(box);box.addView(a.action(a,"Android settings",()->a.open(new Intent(Settings.ACTION_SETTINGS))));ScrollView scroll=new ScrollView(a);scroll.addView(box);full("Control center",scroll);
    }
    interface NumberAction{void apply(int value);}
    void slider(LinearLayout box,String name,int value,int max,NumberAction action){GlassPanel glass=new GlassPanel(a,a,"home");LinearLayout content=a.column(a);content.setPadding(a.dp(16),a.dp(14),a.dp(16),a.dp(12));content.addView(a.text(a,name,15));SeekBar bar=new SeekBar(a);bar.setMax(max);bar.setProgress(value);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int value,boolean user){if(user)try{action.apply(value);}catch(Exception ignored){}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});content.addView(bar,new LinearLayout.LayoutParams(-1,a.dp(44)));glass.addView(content);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,a.dp(7),0,a.dp(7));box.addView(glass,p);}
    void tile(GridLayout grid,String label,String subtitle,boolean active,Runnable action){LinearLayout content=a.column(a);content.setPadding(a.dp(14),a.dp(14),a.dp(10),a.dp(12));LinearLayout heading=a.row(a);heading.addView(glyph(label),new LinearLayout.LayoutParams(a.dp(25),a.dp(25)));TextView title=a.text(a,label.equals("Airplane mode")?"Airplane":label,16);title.setPadding(a.dp(9),0,0,0);title.setTypeface(Typeface.create("sans-serif-medium",0));heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));content.addView(heading);TextView detail=a.text(a,subtitle,12);detail.setPadding(0,a.dp(9),0,0);content.addView(detail);FrameLayout card;if(active){card=new FrameLayout(a);android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(0xff247cfa);background.setCornerRadius(a.dp(24));card.setBackground(background);}else card=new GlassPanel(a,a,"home");card.addView(content);card.setContentDescription(label);card.setOnClickListener(v->action.run());GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.width=0;p.height=a.dp(100);p.setMargins(a.dp(4),a.dp(4),a.dp(4),a.dp(4));grid.addView(card,p);}
    View glyph(String kind){return new View(a){final Paint paint=new Paint(3);@Override protected void onDraw(Canvas c){c.save();c.scale(getWidth()/28f,getHeight()/28f);paint.setColor(Color.WHITE);paint.setStrokeWidth(2);paint.setStyle(Paint.Style.STROKE);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);if(kind.equals("Wi-Fi")){c.drawArc(new RectF(1,3,27,29),225,90,false,paint);c.drawArc(new RectF(6,12,22,28),225,90,false,paint);paint.setStyle(Paint.Style.FILL);c.drawCircle(14,24,1.6f,paint);}else if(kind.equals("Bluetooth")){Path path=new Path();path.moveTo(8,7);path.lineTo(21,20);path.lineTo(14,26);path.lineTo(14,2);path.lineTo(21,8);path.lineTo(8,21);c.drawPath(path,paint);}else if(kind.equals("Mobile data")){paint.setStyle(Paint.Style.FILL);for(int i=0;i<4;i++)c.drawRoundRect(3+i*6,20-i*5,6+i*6,26,1,1,paint);}else{Path path=new Path();path.moveTo(3,15);path.lineTo(12,11);path.lineTo(12,3);path.lineTo(16,3);path.lineTo(16,11);path.lineTo(25,15);path.lineTo(25,18);path.lineTo(16,16);path.lineTo(16,23);path.lineTo(20,25);path.lineTo(8,25);path.lineTo(12,23);path.lineTo(12,16);path.lineTo(3,18);path.close();c.drawPath(path,paint);}c.restore();}};}
    void torch(){if(a.checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.CAMERA},70);return;}try{CameraManager cameras=a.getSystemService(CameraManager.class);if(torchId==null)for(String id:cameras.getCameraIdList()){CameraCharacteristics info=cameras.getCameraCharacteristics(id);if(Boolean.TRUE.equals(info.get(CameraCharacteristics.FLASH_INFO_AVAILABLE))){torchId=id;break;}}if(torchId==null){a.toast("No flashlight is available on this device.");return;}cameras.setTorchMode(torchId,!torchOn);torchOn=!torchOn;}catch(Exception e){a.toast("The flashlight is busy or unavailable.");}}
    void media(LinearLayout box){if(AuraNotifications.active==null)return;try{MediaSessionManager manager=a.getSystemService(MediaSessionManager.class);java.util.List<MediaController> sessions=manager.getActiveSessions(new ComponentName(a,AuraNotifications.class));if(sessions.isEmpty())return;MediaController controller=sessions.get(0);MediaMetadata data=controller.getMetadata();if(data==null)return;GlassPanel card=new GlassPanel(a,a,"home");LinearLayout content=a.column(a);content.setPadding(a.dp(16),a.dp(14),a.dp(16),a.dp(12));content.addView(a.text(a,String.valueOf(data.getText(MediaMetadata.METADATA_KEY_TITLE)),18));CharSequence artist=data.getText(MediaMetadata.METADATA_KEY_ARTIST);if(artist!=null)content.addView(a.text(a,artist.toString(),13));LinearLayout buttons=a.row(a);buttons.addView(a.action(a,"Previous",()->controller.getTransportControls().skipToPrevious()));PlaybackState state=controller.getPlaybackState();boolean playing=state!=null&&state.getState()==PlaybackState.STATE_PLAYING;buttons.addView(a.action(a,playing?"Pause":"Play",()->{if(playing)controller.getTransportControls().pause();else controller.getTransportControls().play();}));buttons.addView(a.action(a,"Next",()->controller.getTransportControls().skipToNext()));content.addView(buttons);card.addView(content);box.addView(card);}catch(Exception ignored){}}
